using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and human civilization." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen has over 15 years of experience in software engineering and distributed systems. She received her PhD from MIT and has published extensively on cloud computing architectures.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Kim", Title = "Associate Professor of Mathematics", Bio = "Dr. Kim specializes in applied mathematics and statistical modeling. His research focuses on machine learning theory and optimization algorithms.", Email = "rkim@university.edu" },
            new() { Id = 3, Name = "Prof. Sarah Mitchell", Title = "Professor of English", Bio = "Prof. Mitchell is an award-winning author and literary critic. She specializes in contemporary American fiction and creative writing pedagogy.", Email = "smitchell@university.edu" },
            new() { Id = 4, Name = "Dr. James Park", Title = "Professor of Physics", Bio = "Dr. Park leads the university's quantum computing research lab. He has contributed to breakthrough discoveries in quantum entanglement and superconductivity.", Email = "jpark@university.edu" },
            new() { Id = 5, Name = "Dr. Maria Garcia", Title = "Associate Professor of History", Bio = "Dr. Garcia specializes in Latin American history and post-colonial studies. Her recent book on cultural exchange in the Americas won the National History Prize.", Email = "mgarcia@university.edu" },
            new() { Id = 6, Name = "Dr. David Lee", Title = "Assistant Professor of Computer Science", Bio = "Dr. Lee's research focuses on artificial intelligence and natural language processing. He previously worked at a leading AI research lab before joining academia.", Email = "dlee@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Science Hall 201", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures & Algorithms", Description = "Advanced study of data structures including trees, graphs, and hash tables. Analysis of algorithm complexity and design patterns for efficient problem solving.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Room = "Science Hall 305", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = false },
            new() { Id = 3, Code = "CS 450", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search algorithms, knowledge representation, machine learning fundamentals, and neural networks.", Credits = 3, Schedule = "Mon/Wed 2:00–3:30 PM", Room = "Tech Building 110", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[5], IsFeatured = true },
            new() { Id = 4, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of equations.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Math Building 102", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = false },
            new() { Id = 5, Code = "MATH 310", Title = "Probability & Statistics", Description = "Comprehensive introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM", Room = "Math Building 205", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = true },
            new() { Id = 6, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop academic writing skills through essay composition, rhetorical analysis, research methods, and peer review workshops.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Humanities 301", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[2], IsFeatured = false },
            new() { Id = 7, Code = "ENG 350", Title = "Modern American Literature", Description = "Survey of American literature from 1945 to the present. Explores themes of identity, technology, and social change through major works.", Credits = 3, Schedule = "Tue/Thu 3:00–4:30 PM", Room = "Humanities 215", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[2], IsFeatured = false },
            new() { Id = 8, Code = "PHYS 201", Title = "Classical Mechanics", Description = "Newtonian mechanics, conservation laws, oscillations, gravitation, and introduction to Lagrangian mechanics.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Room = "Physics Lab 101", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[3], IsFeatured = true },
            new() { Id = 9, Code = "PHYS 410", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, angular momentum, spin, and applications to atomic systems.", Credits = 4, Schedule = "Tue/Thu 9:00–10:30 AM", Room = "Physics Lab 301", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[3], IsFeatured = false },
            new() { Id = 10, Code = "HIST 101", Title = "World Civilizations", Description = "Survey of major world civilizations from antiquity to 1500 CE. Examines political, economic, and cultural developments across regions.", Credits = 3, Schedule = "Mon/Wed 10:00–11:30 AM", Room = "Liberal Arts 104", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[4], IsFeatured = false },
            new() { Id = 11, Code = "HIST 320", Title = "History of the Americas", Description = "Exploration of North and South American history from pre-Columbian civilizations through the modern era, with emphasis on cultural exchange.", Credits = 3, Schedule = "Tue/Thu 2:00–3:30 PM", Room = "Liberal Arts 210", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[4], IsFeatured = true },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0
            && _courses.Any(c => c.Id == request.CourseId);
    }
}

