@page "/courses"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" class="filter-form">
    <input type="text" name="search" value="@Search" placeholder="Search courses, instructors..." />
    <select name="departmentId">
        <option value="">All Departments</option>
        @foreach (var dept in CatalogService.GetDepartments())
        {
            <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
        }
    </select>
    <button type="submit" class="btn-primary">Search</button>
</form>

@{
    var courses = CatalogService.GetCourses(Search, DepartmentId);
}

<p class="results-count">@courses.Count course(s) found</p>

<div class="course-list">
    @foreach (var course in courses)
    {
        <div class="course-list-item">
            <div class="course-list-header">
                <h2><a href="/courses/@course.Id">@course.Code: @course.Title</a></h2>
                <span class="badge">@course.Credits credits</span>
            </div>
            <p>@course.Description</p>
            <div class="course-meta">
                <span>📅 @course.Schedule</span>
                <span>👤 @course.Instructor.Name</span>
                <span>🏛️ @course.Department.Name</span>
            </div>
        </div>
    }
</div>

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/courses/{Id:int}"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
    <a href="/courses">Back to Courses</a>
}
else
{
    <PageTitle>@course.Code: @course.Title - University Course Catalog</PageTitle>

    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo;
        <a href="/courses">Courses</a> &rsaquo;
        <a href="/courses?departmentId=@course.DepartmentId">@course.Department.Name</a> &rsaquo;
        <span>@course.Code</span>
    </nav>

    <article class="course-detail">
        <header>
            <h1>@course.Code: @course.Title</h1>
            <span class="badge">@course.Department.Name</span>
        </header>

        <section class="detail-grid">
            <div class="detail-main">
                <h2>Description</h2>
                <p>@course.Description</p>

                <h2>Schedule &amp; Location</h2>
                <dl>
                    <dt>Schedule</dt>
                    <dd>@course.Schedule</dd>
                    <dt>Room</dt>
                    <dd>@course.Room</dd>
                    <dt>Credits</dt>
                    <dd>@course.Credits</dd>
                </dl>
            </div>

            <aside class="detail-sidebar">
                <div class="instructor-card">
                    <h2>Instructor</h2>
                    <h3>@course.Instructor.Name</h3>
                    <p class="instructor-title">@course.Instructor.Title</p>
                    <p>@course.Instructor.Bio</p>
                    <p class="instructor-email">📧 @course.Instructor.Email</p>
                </div>

                <a href="/enroll?courseId=@course.Id" class="btn-primary enroll-btn">Request Enrollment</a>
            </aside>
        </section>
    </article>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private UniversityCourseCatalog.Models.Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enrollment Request - University Course Catalog</PageTitle>

<nav class="breadcrumb">
    <a href="/">Home</a> &rsaquo;
    <a href="/courses">Courses</a> &rsaquo;
    <span>Enrollment Request</span>
</nav>

<h1>Enrollment Request</h1>

@if (Submitted)
{
    <div class="success-message">
        <h2>Request Submitted!</h2>
        <p>Your enrollment request has been received. You will be notified by email once it has been processed.</p>
        <a href="/courses" class="btn-primary">Back to Courses</a>
    </div>
}
else
{
    <p>Fill out the form below to request enrollment in a course. All fields are required.</p>

    <form method="post" class="enroll-form">
        <AntiforgeryToken />

        <div class="form-group">
            <label for="studentName">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" required />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" required placeholder="e.g., STU-12345" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <select id="courseId" name="Model.CourseId" required>
                <option value="">-- Select a Course --</option>
                @foreach (var course in CatalogService.GetCourses())
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Code: @course.Title (@course.Credits credits)</option>
                }
            </select>
        </div>

        <button type="submit" class="btn-primary">Submit Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        // Check if form was submitted (POST)
        if (!string.IsNullOrWhiteSpace(Model.StudentName) && !string.IsNullOrWhiteSpace(Model.StudentId) && Model.CourseId > 0)
        {
            Submitted = CatalogService.SubmitEnrollmentRequest(Model);
        }
    }
}

