.instructor-title { color: var(--text-muted); font-style: italic; margin-bottom: 0.75rem; }
.instructor-email { margin-top: 0.75rem; font-size: 0.9rem; }

.enroll-btn { display: block; text-align: center; width: 100%; }

/* Enrollment Form */
